// StoryProjectsSection.jsx

import "./StoryProjectsSection.css";
import { motion } from "framer-motion";
import tem from "../assets/tem.png";
import satva from "../assets/satva.png";
import sat from "../assets/sat.png";
import poarr from "../assets/poarr.png";
import atr from "../assets/atr.png";
import { Link, Links } from "react-router-dom";

const projects = [
  {
    id: 1,
    title: "Sattva",
    location: "Bangalore",
    image:
    sat,
  },

  {
    id: 2,
    title: "Temple Crest",
    location: "Bangalore",
    image:tem,
  },

  {
    id: 3,
    title: "ITQE",
    location: "Bangalore",
    image:satva,
  },

  {
    id: 4,
    title: "POARR",
    location: "Bangalore",
    image:
    poarr,
  },

  {
    id: 5,
    title: "ATR",
    location: "Bangalore",
    image:
      atr,
  },
];

export default function StoryProjectsSection() {
  return (
    <section className="cinematic-projects">

      {/* ===================================== */}
      {/* CINEMATIC ANIMATED BACKGROUND */}
      {/* ===================================== */}

      <div className="cinematic-bg">

        {/* Floating Gradient Spheres */}
        <div className="gradient-sphere sphere1"></div>
        <div className="gradient-sphere sphere2"></div>
        <div className="gradient-sphere sphere3"></div>

        {/* Animated Glass Panels */}
        <div className="glass-panel panel1"></div>
        <div className="glass-panel panel2"></div>

        {/* Moving Light Beams */}
        <div className="light-beam beam1"></div>
        <div className="light-beam beam2"></div>
        <div className="light-beam beam3"></div>

        {/* Cinematic Grid */}
        <div className="grid-overlay"></div>

        {/* Noise Texture */}
        <div className="noise"></div>

      </div>

      {/* ===================================== */}
      {/* HEADER */}
      {/* ===================================== */}

      <div className="section-header">

        {/* <motion.span
          initial={{ opacity: 0, y: 40 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.7 }}
          viewport={{ once: true }}
        >
          OUR PROJECTS
        </motion.span> */}

        <motion.h2
          initial={{ opacity: 0, y: 80 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 1 }}
          viewport={{ once: true }}
        >
         
          CINEMATIC GLASS
          <br />
          <span>
          Architecture </span>
        </motion.h2>

        <motion.p
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          transition={{ delay: 0.3 }}
          viewport={{ once: true }}
        >
          Luxury architecture experiences crafted with
          immersive cinematic visuals, premium glass
          aesthetics, fluid animations, and modern
          storytelling.
        </motion.p>

      </div>

      {/* ===================================== */}
      {/* PROJECTS GRID */}
      {/* ===================================== */}

      <div className="projects-grid">

        {projects.map((project, index) => (

          <motion.div
            key={project.id}
            className={`glass-card ${
              index === 0 ? "featured" : ""
            }`}

            initial={{
              opacity: 0,
              y: 80,
            }}

            whileInView={{
              opacity: 1,
              y: 0,
            }}

            transition={{
              duration: 0.9,
              delay: index * 0.12,
            }}

            viewport={{ once: true }}

            whileHover={{
              y: -15,
              scale: 1.02,
            }}
          >

            {/* ======================= */}
            {/* IMAGE */}
            {/* ======================= */}

            <div className="card-image">

              <img
                src={project.image}
                alt={project.title}
              />

              {/* Dark Overlay */}
              <div className="dark-overlay"></div>

              {/* Glass Reflection */}
              <div className="glass-reflection"></div>

            </div>

            {/* ======================= */}
            {/* CONTENT */}
            {/* ======================= */}

            <div className="card-content">

              <div className="content-left">

                <h3>{project.title}</h3>

                <p>{project.location}</p>

              </div>
<Link to="/contactus">
              <button>
                Explore
              </button>
              </Link>

            </div>

          </motion.div>

        ))}

      </div>

    </section>
  );
}